import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchTemporalAnalysis, fetchAccountCorrelation } from '../../store/slices/analyticsSlice';
import './Analytics.css';

const Analytics: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { 
    temporalAnalysis, 
    correlationData,
    isLoadingTemporal, 
    isLoadingCorrelation,
    temporalError,
    correlationError
  } = useSelector((state: RootState) => state.analytics);

  useEffect(() => {
    // Fetch temporal analysis for a default account
    dispatch(fetchTemporalAnalysis({ accountName: 'IPS_TM_10' }));
    dispatch(fetchAccountCorrelation(['IPS_TM_10']));
  }, [dispatch]);

  if (isLoadingTemporal || isLoadingCorrelation) {
    return (
      <div className="analytics">
        <div className="loading">Loading analytics data...</div>
      </div>
    );
  }

  if (temporalError || correlationError) {
    return (
      <div className="analytics">
        <div className="error">Error loading analytics: {temporalError || correlationError}</div>
      </div>
    );
  }

  // Get the temporal analysis for the default account
  const data = temporalAnalysis['IPS_TM_10'];
  
  // Calculate overall statistics from hourly performance
  const hourlyStats = data?.hourly_performance ? Object.values(data.hourly_performance) : [];
  const totalTrades = hourlyStats.reduce((sum, hour) => sum + hour.total_trades, 0);
  const totalPnl = hourlyStats.reduce((sum, hour) => sum + hour.total_pnl, 0);
  const winningTrades = hourlyStats.reduce((sum, hour) => sum + hour.winning_trades, 0);
  const overallWinRate = totalTrades > 0 ? (winningTrades / totalTrades) * 100 : 0;

  return (
    <div className="analytics">
      <h1>Trading Analytics</h1>
      
      <div className="analytics-grid">
        <div className="analytics-card">
          <h3>Performance Metrics</h3>
          <div className="metrics-list">
            <div className="metric-row">
              <span>Account:</span>
              <span>{data?.account_name || 'N/A'}</span>
            </div>
            <div className="metric-row">
              <span>Symbol:</span>
              <span>{data?.symbol || 'N/A'}</span>
            </div>
            <div className="metric-row">
              <span>Win Rate:</span>
              <span>{overallWinRate.toFixed(2)}%</span>
            </div>
            <div className="metric-row">
              <span>Total Trades:</span>
              <span>{totalTrades}</span>
            </div>
            <div className="metric-row">
              <span>Total P&L:</span>
              <span>{totalPnl.toFixed(2)}</span>
            </div>
          </div>
        </div>

        <div className="analytics-card">
          <h3>Temporal Patterns</h3>
          <div className="temporal-section">
            <h4>Best Trading Hours</h4>
            <div className="pattern-list">
              {data?.hourly_performance?.length ? (
                data.hourly_performance.slice(0, 5).map((hour: any, index: number) => (
                  <div key={index} className="pattern-item">
                    <span>{hour.hour}:00</span>
                    <span>{hour.avg_profit?.toFixed(2)} avg P&L</span>
                  </div>
                ))
              ) : (
                <div className="no-data">No temporal data available</div>
              )}
            </div>
          </div>

          <div className="temporal-section">
            <h4>Best Trading Days</h4>
            <div className="pattern-list">
              {data?.daily_performance?.length ? (
                data.daily_performance.slice(0, 5).map((day: any, index: number) => (
                  <div key={index} className="pattern-item">
                    <span>{day.day_of_week}</span>
                    <span>{day.avg_profit?.toFixed(2)} avg P&L</span>
                  </div>
                ))
              ) : (
                <div className="no-data">No daily data available</div>
              )}
            </div>
          </div>
        </div>

        <div className="analytics-card">
          <h3>Account Comparison</h3>
          <div className="comparison-table">
            <div className="table-header">
              <span>Account</span>
              <span>Trades</span>
              <span>Win Rate</span>
              <span>Avg P&L</span>
              <span>Sharpe</span>
            </div>
            {correlationData?.accounts?.length ? (
              correlationData.accounts.map((account: any, index: number) => (
                <div key={index} className="table-row">
                  <span>{account.account_name}</span>
                  <span>{account.total_trades}</span>
                  <span>{account.win_rate?.toFixed(1)}%</span>
                  <span>{account.avg_profit?.toFixed(2)}</span>
                  <span>{account.sharpe_ratio?.toFixed(2)}</span>
                </div>
              ))
            ) : (
              <div className="no-data">No comparison data available</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Analytics;
